const modal = document.getElementById('researchModal');
const modalContent = document.getElementById('modalContent');
function escapeHtml(str){return String(str).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function openPaper(id){
  const p=papers[id]; if(!p)return;
  modalContent.innerHTML=`<div class="modal-head"><div><span class="tag">${escapeHtml(p.tag)}</span><h2>${escapeHtml(p.title)}</h2></div><button class="close" onclick="closeResearch()" aria-label="Close">×</button></div><div class="modal-body">
  <section class="modal-section"><h4>Author & Submission</h4><p><strong>${escapeHtml(p.author)}</strong><br>${escapeHtml(p.affiliation)}<br>${escapeHtml(p.date)}</p></section>
  <section class="modal-section"><h4>Executive Summary</h4><p>${escapeHtml(p.summary)}</p></section>
  <section class="modal-section"><h4>Research Methodology</h4><p>${escapeHtml(p.methodology)}</p></section>
  ${p.scope?`<section class="modal-section"><h4>Geographic Scope</h4><div class="scope">${p.scope.map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div></section>`:''}
  <section class="modal-section"><h4>Key Research Findings</h4><ol class="bullet-list">${p.findings.map((x,i)=>`<li data-n="${i+1}">${escapeHtml(x)}</li>`).join('')}</ol></section>
  <section class="modal-section"><h4>Policy & Strategic Recommendations</h4><ol class="bullet-list">${p.recommendations.map((x,i)=>`<li data-n="${i+1}">${escapeHtml(x)}</li>`).join('')}</ol></section>
  <section class="modal-section"><h4>Keywords</h4><div class="modal-keywords">${p.keywords.map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div></section>
  ${p.gallery?`<section class="modal-section"><h4>ICBIID 2026 · Research & Conference Gallery</h4><p>Research presentation, conference participation, networking, stage and certificate-related photographs supplied for the ICBIID research portfolio.</p><div class="modal-gallery">${p.gallery.map((x,i)=>`<img src="${x}" alt="ICBIID 2026 research photo ${i+1}" loading="lazy">`).join('')}</div></section>`:''}
  </div>`;
  modal.classList.add('open');document.body.style.overflow='hidden';
}
function closeResearch(){modal.classList.remove('open');document.body.style.overflow='';}
window.openPaper=openPaper;window.closeResearch=closeResearch;
modal.addEventListener('click',e=>{if(e.target===modal)closeResearch()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeResearch()});


