const artworkGrid = document.getElementById('artworkGrid');
function renderArtworkGrid(filter='all'){
  artworkGrid.innerHTML = creativeArtworks.map((a,i)=>{
    const visible = filter==='all' || (filter==='calendar' ? false : filter==='illustration' ? a[2]==='Digital Illustration' : a[2]==='Concept & Campaign');
    return `<article class="art-card" data-category="${a[2]==='Digital Illustration'?'illustration':'concept'}" ${visible?'':'style="display:none"'} tabindex="0" onclick="openArtwork(${i})" onkeydown="if(event.key==='Enter'||event.key===' ')openArtwork(${i})" aria-label="View ${escapeHtml(a[0])}">
      <div class="art-visual"><img loading="lazy" src="${escapeHtml(a[4])}" alt="${escapeHtml(a[0])} — original artwork"></div>
      <div class="art-body"><small>PAGE ${i+1} · ${escapeHtml(a[2])}</small><h4>${escapeHtml(a[0])}</h4><div class="art-tags">${a[3].map(t=>`<span>${escapeHtml(t)}</span>`).join('')}</div></div><div class="creative-badge">View Artwork ↗</div>
    </article>`;
  }).join('');
}
renderArtworkGrid();

document.querySelectorAll('.creative-filter').forEach(btn=>btn.addEventListener('click',()=>{
  document.querySelectorAll('.creative-filter').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-selected','false')});
  btn.classList.add('active');btn.setAttribute('aria-selected','true');
  const f=btn.dataset.filter;
  const feature=document.querySelector('.calendar-feature');
  const artworkHead=document.querySelector('.artwork-section-head');
  if(f==='calendar'){
    feature.style.display='';
    artworkGrid.style.display='none';
    artworkHead.style.display='none';
  } else {
    feature.style.display=f==='all'?'':'none';
    artworkGrid.style.display='';
    artworkHead.style.display='flex';
    renderArtworkGrid(f)
  }
}));

const calendarPages = Array.from({length:13},(_,i)=>`assets/calendar-pages/page-${String(i+1).padStart(2,'0')}.png`);
const calendarLabels = ['Cover Page','January 2026','February 2026','March 2026','April 2026','May 2026','June 2026','July 2026','August 2026','September 2026','October 2026','November 2026','December 2026'];
let calendarIndex=0;
const calendarModal=document.getElementById('calendarModal'),calendarModalContent=document.getElementById('calendarModalContent');
function renderCalendar(){
  calendarModalContent.innerHTML=`<div class="calendar-viewer"><div class="calendar-viewer-top"><div><span class="creative-kicker">2026 CORPORATE STRATEGY & MOTIVATIONAL DESK CALENDAR</span><h2>${escapeHtml(calendarLabels[calendarIndex])}</h2></div><button class="close" onclick="closeCalendar()" aria-label="Close calendar viewer">×</button></div><div class="calendar-frame"><img loading="lazy" src="${calendarPages[calendarIndex]}" alt="${escapeHtml(calendarLabels[calendarIndex])} calendar page"></div><div class="calendar-controls"><button class="calendar-control" onclick="prevCalendar()">← Previous</button><span class="calendar-counter">${calendarIndex+1} / ${calendarPages.length}</span><button class="calendar-control" onclick="nextCalendar()">Next →</button></div><div class="calendar-thumb-row">${calendarPages.map((src,i)=>`<button class="calendar-thumb ${i===calendarIndex?'active':''}" onclick="setCalendar(${i})" aria-label="Open ${escapeHtml(calendarLabels[i])}"><img loading="lazy" src="${src}" alt=""></button>`).join('')}</div></div>`;
}
function openCalendar(index=0){calendarIndex=Math.max(0,Math.min(calendarPages.length-1,index));renderCalendar();calendarModal.classList.add('open');document.body.style.overflow='hidden';}
function closeCalendar(){calendarModal.classList.remove('open');document.body.style.overflow='';}
function nextCalendar(){calendarIndex=(calendarIndex+1)%calendarPages.length;renderCalendar()}
function prevCalendar(){calendarIndex=(calendarIndex-1+calendarPages.length)%calendarPages.length;renderCalendar()}
function setCalendar(i){calendarIndex=i;renderCalendar()}
window.openCalendar=openCalendar;window.closeCalendar=closeCalendar;window.nextCalendar=nextCalendar;window.prevCalendar=prevCalendar;window.setCalendar=setCalendar;
calendarModal.addEventListener('click',e=>{if(e.target===calendarModal)closeCalendar()});

const artworkModal=document.getElementById('artworkModal'),artworkModalContent=document.getElementById('artworkModalContent');
function openArtwork(i){const a=creativeArtworks[i]; artworkModalContent.innerHTML=`<div class="art-lightbox"><div class="modal-head" style="position:relative;margin:-28px -28px 20px"><div><span class="tag">PAGE ${i+1} · ${escapeHtml(a[2])}</span><h2>${escapeHtml(a[0])}</h2></div><button class="close" onclick="closeArtwork()" aria-label="Close artwork viewer">×</button></div><div class="art-lightbox-media"><div class="art-visual"><img loading="lazy" src="${escapeHtml(a[4])}" alt="${escapeHtml(a[0])} — original artwork"></div></div><div class="art-lightbox-copy"><h2>${escapeHtml(a[0])}</h2><p>${escapeHtml(a[1])}</p><div class="art-tags">${a[3].map(t=>`<span>${escapeHtml(t)}</span>`).join('')}</div></div></div>`;artworkModal.classList.add('open');document.body.style.overflow='hidden';}
function closeArtwork(){artworkModal.classList.remove('open');document.body.style.overflow='';}
window.openArtwork=openArtwork;window.closeArtwork=closeArtwork;
artworkModal.addEventListener('click',e=>{if(e.target===artworkModal)closeArtwork()});
