const portfolioPhotos = [
  {src:'assets/photo-market-snacks.jpg',title:'Market colours',alt:'A colourful street snack and candy stall'},
  {src:'assets/photo-pottery-display.jpg',title:'Earth & craft',alt:'Traditional terracotta pottery display'},
  {src:'assets/photo-pottery-figures.jpg',title:'Handmade details',alt:'Handcrafted pottery figures and ornaments'},
  {src:'assets/photo-goddess-sculpture.jpg',title:'Sculptural detail',alt:'Decorative goddess sculpture in a traditional craft shop'},
  {src:'assets/photo-bamboo-rattan.jpg',title:'Natural materials',alt:'Bamboo and rattan furniture in a craft market'},
  {src:'assets/photo-rattan-market.jpg',title:'Everyday commerce',alt:'Rattan shop and its vendor'},
  {src:'assets/photo-chicks.jpg',title:'Life in motion',alt:'A group of young chicks'},
  {src:'assets/photo-green-leaves.jpg',title:'Close to nature',alt:'Fresh green leaves with a tiny insect'}
];
function renderPortfolioPhotos(){
 const grid=document.getElementById('photoGrid'); if(!grid || grid.dataset.rendered==='true') return;
 grid.innerHTML=portfolioPhotos.map((p,i)=>`<article class="photo-card"><button type="button" class="photo-open" data-photo-index="${i}" aria-label="View photo: ${p.title}"><img loading="lazy" src="${p.src}" alt="${p.alt}"><span class="photo-caption"><strong>${p.title}</strong><span>View photograph ↗</span></span></button></article>`).join('');
 grid.dataset.rendered='true';
 grid.addEventListener('click',function(e){const b=e.target.closest('[data-photo-index]');if(!b)return;const p=portfolioPhotos[Number(b.dataset.photoIndex)];let modal=document.getElementById('photoLightbox');if(!modal){modal=document.createElement('div');modal.id='photoLightbox';modal.className='photo-lightbox';modal.innerHTML='<button type="button" class="photo-lightbox-close" aria-label="Close photograph">×</button><figure><img alt=""><figcaption></figcaption></figure>';document.body.appendChild(modal);modal.addEventListener('click',ev=>{if(ev.target===modal||ev.target.closest('.photo-lightbox-close'))modal.classList.remove('open')});document.addEventListener('keydown',ev=>{if(ev.key==='Escape')modal.classList.remove('open')});}const img=modal.querySelector('img');img.src=p.src;img.alt=p.alt;modal.querySelector('figcaption').textContent=p.title;modal.classList.add('open');});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',renderPortfolioPhotos);else renderPortfolioPhotos();

