const credentialModal = document.getElementById('credentialModal');
const credentialModalContent = document.getElementById('credentialModalContent');
function credentialKey(e,id){if(e.key==='Enter'||e.key===' '){e.preventDefault();openCredential(id)}}
function openCredential(id){const c=credentials[id];if(!c)return;credentialModalContent.innerHTML=`<div class="modal-head"><div><span class="tag">PROFESSIONAL CREDENTIAL</span><h2>${escapeHtml(c.title)}</h2></div><button class="close" onclick="closeCredential()" aria-label="Close credential details">×</button></div><div class="credential-modal-body"><div class="credential-preview"><span class="credential-preview-label">HD PREVIEW</span><img loading="lazy" src="${escapeHtml(c.preview)}" alt="HD preview of ${escapeHtml(c.title)}"></div><div class="credential-info"><div class="credential-kicker">ISSUER</div><h3>${escapeHtml(c.title)}</h3><p class="credential-issuer">${escapeHtml(c.issuer)}</p><dl class="credential-facts"><div class="credential-fact"><dt>Recipient</dt><dd>${escapeHtml(c.recipient)}</dd></div>${c.certificateNo?`<div class="credential-fact"><dt>Certificate No.</dt><dd>${escapeHtml(c.certificateNo)}</dd></div>`:''}<div class="credential-fact"><dt>Date</dt><dd>${escapeHtml(c.date)}</dd></div>${c.duration?`<div class="credential-fact"><dt>Duration</dt><dd>${escapeHtml(c.duration)}</dd></div>`:''}<div class="credential-fact"><dt>Course Details</dt><dd>${escapeHtml(c.course)}</dd></div><div class="credential-fact"><dt>Key Topics</dt><dd>${escapeHtml(c.topics)}</dd></div><div class="credential-fact"><dt>Venue</dt><dd>${escapeHtml(c.venue)}</dd></div></dl></div></div>`;credentialModal.classList.add('open');document.body.style.overflow='hidden'}
function closeCredential(){credentialModal.classList.remove('open');document.body.style.overflow=''}
window.openCredential=openCredential;window.closeCredential=closeCredential;window.credentialKey=credentialKey;credentialModal.addEventListener('click',e=>{if(e.target===credentialModal)closeCredential()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&credentialModal.classList.contains('open'))closeCredential()});
const storyModal = document.getElementById('storyModal');
const storyModalContent = document.getElementById('storyModalContent');
function storyKey(e,id){if(e.key==='Enter'||e.key===' '){e.preventDefault();openStory(id)}}
function storyParagraph(p){const esc=escapeHtml(p);const isStage=/^\([^)]{1,100}\)$/.test(p)||/^\[.*\]$/.test(p);const isDialogue=/^[^:]{1,35}:/.test(p);const cls=isStage?'stage':isDialogue?'dialogue':'';return `<p class="${cls}">${esc}</p>`}
function openStory(id){const st=storyData[id];if(!st)return;const content=st.content?st.content.map(storyParagraph).join(''):`<div class="story-preview-note"><strong>Preview only.</strong><br><br>${escapeHtml(st.teaser)}<br><br>The full manuscript for this story is not present in the currently available source files, so this card intentionally does not invent or reproduce missing content.</div>`;storyModalContent.innerHTML=`<div class="modal-head"><div><span class="tag">${escapeHtml(st.category)}</span><h2>${escapeHtml(st.title)}</h2><div class="story-meta"><span>${escapeHtml(st.en)}</span><span>${st.content?'FULL STORY':'PREVIEW ONLY'}</span></div></div><button class="close story-close" onclick="closeStory()" aria-label="Close story reader">×</button></div><div class="story-reader-body"><div class="story-intro"><div><div class="story-reading-label">STORYTELLING & CONTENT CREATION</div><p class="story-teaser">${escapeHtml(st.teaser)}</p></div><div><div class="story-reading-label">CHARACTER BREAKDOWN</div><div class="character-list">${st.chars.map(c=>`<span>${escapeHtml(c)}</span>`).join('')}</div></div></div><div class="story-content">${content}</div></div>`;storyModal.classList.add('open');document.body.style.overflow='hidden';}
function closeStory(){storyModal.classList.remove('open');document.body.style.overflow=''}
window.openStory=openStory;window.closeStory=closeStory;window.storyKey=storyKey;storyModal.addEventListener('click',e=>{if(e.target===storyModal)closeStory()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&storyModal.classList.contains('open'))closeStory()});
document.querySelectorAll('.copy-email').forEach(el=>el.addEventListener('click',async()=>{const email=el.dataset.email;if(navigator.clipboard){try{await navigator.clipboard.writeText(email)}catch(e){}}const tip=el.querySelector('.copy-tip');if(tip){tip.textContent='Copied!';tip.classList.add('show');setTimeout(()=>tip.classList.remove('show'),1400);}}));